package com.qpwflshclub.formal_club.config;
import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpServletRequest;import static org.assertj.core.api.Assertions.*;
class RegistrationProofTest {@Test void proofIsBoundToVerifiedEmailAndBrowserAndConsumed(){var r=new MockHttpServletRequest();assertThatThrownBy(()->RegistrationProof.require(r,"one@example.com")).hasMessageContaining("400");RegistrationProof.verified(r,"one@example.com");RegistrationProof.require(r,"ONE@example.com");assertThatThrownBy(()->RegistrationProof.require(r,"two@example.com")).hasMessageContaining("400");assertThatThrownBy(()->RegistrationProof.require(new MockHttpServletRequest(),"one@example.com")).hasMessageContaining("400");RegistrationProof.consume(r);assertThatThrownBy(()->RegistrationProof.require(r,"one@example.com")).hasMessageContaining("400");}}
